const tarifa = (m) => {
  m = String(m || '');
  if (m.startsWith('claude')) return m.replace(/-(\d+)-(\d+)$/, '-$1.$2');
  if (m.includes('flash-lite')) return 'gemini-3.5-flash-lite';
